import React,{useState, useRef, useEffect} from "react";
import "../styles.css";
import Carousel from 'react-elastic-carousel';
import chatResponse from "./chatResponse";
import SendIcon from "./boticons/SendIcons";
import MicIcon from "./boticons/MicIcon";
import axios from "axios";
import SpeechRecognition, { useSpeechRecognition } from "react-speech-recognition";
import { type } from "@testing-library/user-event/dist/type";

const initialMessages = [
  {
    id: 1,
    author: "AILifebot",
    message:
      "👋 Hi​! I'm a AILifebot Virtual Assistant. Let me know if you have any questions about us!"
  }
];

const Chatbot = () => {
  const [messages, setMessages] = useState(initialMessages);
  const [message, setMessage] = useState("");
  const [activeSuggestion, setactiveSuggestion]= useState(0);
  const [filteredSuggestions, setfilteredSuggestions] = useState([]);
  const [showSuggestions, setshowSuggestions] = useState(false);
  const [userInput, setuserInput] = useState("");
  const [chatData, setchatData] = useState(chatResponse.response_items);
  const { transcript, resetTranscript } = useSpeechRecognition();
  const [isListening, setIsListening] = useState(false);
  const [responseData, setResponseData] = useState('');
  const [userdata, setUserdata]= useState(null);
  const microphoneRef = useRef(null);
  const inputRef = useRef(null);

  //console.log('messages',messages.map(e=>e.message));
  console.log('userdata',userdata);
  //console.log('formResponse',formResponse);
  console.log("responseData",responseData)
  const messagesEndRef = useRef(null);
  const scrollToBottom = () => {
    messagesEndRef.current.scrollIntoView({ behavior: "smooth" });
  };
  useEffect(scrollToBottom, [messages]);

  useEffect(() => {
    const requestOptions = {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          "session_id": "jhgdj-23hcbj1hbsd",
          "user_response": `${userdata}`,
          //"user_response": "hello",
          "context": {
              "name":"ayush",
              "email":"alfpa@gmail.com",
              "feedback":"I hate this thing"
          }
      })
    };
    fetch('http://64.227.188.97:8000/response', requestOptions)
        .then(response => response.json())
        .then(data => setResponseData(data.response_items));
    }, [userdata]);

  const handleListing = () => {
    if(isListening==false){
        setIsListening(true);
        microphoneRef.current.classList.add("listening");
        SpeechRecognition.startListening({
        continuous: true,
      }); 
    } 
    else if(isListening==true){
        setIsListening(false);
        microphoneRef.current.classList.remove("listening");
        SpeechRecognition.stopListening();
        resetTranscript();
    }
  };
  const handleClick =(inputval)=> {
    console.log('handleClick',inputval);
    let userResponse = responseData[0].element.label_value;
    let professionalForm = /professional_service_form/;
    let labourForm = /labour_service_form/;
    let feedbackForm = /feedback/;
    let feedbackExit= "feedback_exit";
    let labourFormSubmit = "labour_service";
    let professionalFormSubmit = "professional_service";
    //match userresponse value to above and pass in setuserdata;
    console.log('userResponse',userResponse);
    const userInput = inputRef.current.value;
    if(userResponse=="professional_service_form"){
      if(userInput==""){
        userInput = inputval;
      }else if(userInput.includes("-")==true){
        setUserdata(professionalForm);
      }else if(userInput.includes("@")==true){ 
        setUserdata(professionalForm);
      }else if(userInput!==NaN){ 
        setUserdata(professionalFormSubmit);
      }
    }else if(userResponse=="labour_service_form"){
      if(userInput==""){
        userInput = inputval;
      }else if(userInput.includes("-")==true){
        setUserdata(labourForm);
      }else if(userInput.includes("@")==true){  
        setUserdata(labourFormSubmit);
      }
    }else if(userResponse=="feedback"){
      if(userInput==""){
        userInput = inputval;
      }else if(userInput.includes("-")==true){
        setUserdata(feedbackForm);
      }else if(userInput.includes("@")==true){ 
        setUserdata(feedbackForm);
      }else if(userInput.includes("message","test","is","good","nice","hey","how","what","i","are","we")==true){ 
        setUserdata(feedbackExit);
      }
    }else if(message==""){
      setMessage(userInput);
    }else{
      setUserdata(userInput);
    }
  }
  const onChange = (e) => {
    const suggestions = ["What is chabot?", "how it works?", "say hello!!", "Find good products to me", "Need help?", "Tap to cuntinue"];
    const userInput = e.target.value;
    const filteredSuggestions = suggestions.filter(
      suggestion =>
        suggestion.toLowerCase().indexOf(message.toLowerCase()) > -1
    );
    setMessage(userInput);
    setactiveSuggestion({activeSuggestion});
    setfilteredSuggestions(filteredSuggestions);
    setshowSuggestions({showSuggestions: false});
    setuserInput({userInput: e.currentTarget.innerText});
  };
  
  const sendMessage = (msgData) => {
    if(!message){ 
      let message= msgData;        
        setMessages((prevMessages) => [
          ...prevMessages,
          { id: messages.length + 1, author: "User", message }
        ]);
        setMessage("");
    }else{    
      setMessages((prevMessages) => [
        ...prevMessages,
        { id: messages.length + 1, author: "User", message }
      ]);
      setMessage("");
    }
  };

  const onClick = e => {  
    setMessage(e);
    setactiveSuggestion({activeSuggestion:e});
  };
  let suggestionsListComponent;
    if (showSuggestions && message) {
      if (filteredSuggestions.length) {
        suggestionsListComponent = (
          <ul className="suggestions">
            {filteredSuggestions.map((suggestion, index) => {
              let className;

              if (index === activeSuggestion) {
                className = "";
              }

              return (
                <li key={suggestion} onClick={()=>onClick(suggestion)}>
                  {suggestion}
                </li>
              );
            })}
          </ul>
        );
      }
    }
  React.useEffect(() => {
    const lastMessage = messages[messages.length - 1];
    //console.log('lastmessage', lastMessage.message);

    if (lastMessage.author === "User") {
      let botMessage = responseData.map((e,i)=>{
        if(e.element.label_value=="fallback"){
          return(
            <p className="message" key={i}>{e.element.label_body}</p>
          )
        }else if(e.type=="form"){
          let username= lastMessage.message.includes("-")
          let useremail= lastMessage.message.includes("@");
          let serviceForm = responseData[0].element.label_value;
          console.log('lastMessage.message',lastMessage.message);
          switch(true){
            case lastMessage.message.match(/Architect|Builder|Retailer|Contractor|Lighting consultant|Generate BOQ|Newsletter Updates/)!=null:
            return <p className="message">{e.element.form_items[0].textinput_placeholder}</p>
            break;
            case lastMessage.message.match(/Plumber|Electricians/)!=null:
            return <p className="message">{e.element.form_items[0].textinput_placeholder}</p>
            break;
            case lastMessage.message.match(/Feedback|feedback/)!=null:
            return <p className="message">{e.element.form_items[0].textinput_placeholder}</p>
            break;
            case username:
            return <p className="message">{e.element.form_items[1].textinput_placeholder}</p>
            break;
            case useremail:
            return <p className="message">{e.element.form_items[2].textinput_placeholder}</p>
            break;
          }
        }else if(e.type=="list"){
          return(
            <>
            {e.element.list_items.map((b, i)=>{
                return(
                  <span onClick={()=>{setUserdata(b.button_value);}}>
                    {b.button_url_redirect==null?
                    <a href={b.button_url_redirect} target="_blank" key={i} onClick={()=>{setMessage(b.button_text);sendMessage(b.button_text);}}>
                      <button className="chatbotbtn" onClick={()=> {handleClick(b.button_value);}}>{b.button_text}</button>
                    </a>:
                    <a href={b.button_url_redirect} target="_blank" key={i} >
                    <button className="chatbotbtn">{b.button_text}</button>
                  </a>
                  }
                  </span>
                )
              })}
            </>
          )
        }else if(e.type==="carousel"){
          return(
            <>
              <div className="message">
                <Carousel >
                  {e.element.carousel_items.map((c, i)=>{
                    return(
                      <span key={i}>
                          <img
                              style={{ width: "100%",height:"200px" }}
                              src={c.card_image.image_url}
                          />                
                          <h5 className="pt-2 font-weight-bold">{c.card_heading}</h5>
                          <p>{c.card_body}</p>
                          <a href={c.card_buttons[0].button_url_redirect} target="_blank">
                            <button type="button" style={{left:'20%'}} class="chatbotbtn">{c.card_buttons[0].button_text}</button>
                          </a>
                      </span>
                    )
                  })}
                </Carousel>
              </div>
            </>
          )
        }else if(e.type=="form"){
          if(lastMessage.message==/feedback|professional_service_form|labour_service_form/){
            return <p className="message" >{e.element.form_items[0].textinput_placeholder}</p>
          }
        }
      })

      setMessages((prevMessages) => {
        let temp = responseData.map(e=> e.type);
        let result = new Set(temp);
        if(lastMessage.message=="hello"){
          return [
            ...prevMessages,
            {
              id: messages.length + 1,
              author: "AILifebot",
              message: responseData[0].element.label_body
            },{
              message:responseData[1].element.label_body
            },{
              message:responseData[2].element.label_body
            },{
              message:responseData[3].element.list_items.map((e, i)=>{
                return(
                  <span onClick={()=>{setUserdata(e.button_value);}}>
                    {e.button_url_redirect==null?
                      <a href={e.button_url_redirect} target="_blank" key={i} onClick={()=>{setMessage(e.button_value);sendMessage(e.button_value);}}>
                        <button className="chatbotbtn" onClick={()=> {handleClick(e.button_value);}}>{e.button_text}</button>
                      </a>:
                      <a href={e.button_url_redirect} target="_blank" key={i} >
                        <button className="chatbotbtn">{e.button_text}</button>
                      </a>
                    }
                  </span>
                )
              })
            }
          ];
        }else if(result.has('list') || result.has('lable')){
        return [
          ...prevMessages,
          {
            id: messages.length + 1,
            author: "AILifebot",
            message:responseData.map((e, i)=>{
              return(
                  <>
                    <span key={i}>
                      <p className="user-message">{e.element.label_body}</p>
                      <a href={e.element.url_url} key={i} target="_blank">
                        <p className="user-message">{e.element.url_title}</p>
                      </a>
                    </span>
                  </>
              )
            })           
          },
          {
            message: botMessage
          }
        ];
      }else if(result.has('url') || result.has('lable')){
        return [
          ...prevMessages,
          {
            id: messages.length + 1,
            author: "AILifebot",
            message: <div className="message-list">{responseData.map((e, i)=>{
              return(
                <>
                  <p key={i}>{e.element.label_body}</p>
                  <a href={e.element.url_url} key={i} target="_blank">
                    <p>{e.element.url_title}</p>
                  </a>
                </>
              )
            })
          }</div>
            
          },
          {
            message: botMessage
          }
        ];
      }else if(result.has('carousel') || result.has('lable')){
        return [
          ...prevMessages,
          {
            id: messages.length + 1,
            author: "AILifebot",
            message: responseData[0].element.label_body
            
          },
          {
            id: messages.length + 1,
            author: "AILifebot",
            message:botMessage
          }
       ];
      }else if(/feedback|i want to write feedback|write feedback/.test(lastMessage.message)){
        return [
          ...prevMessages,
          {
            id: messages.length + 1,
            author: "AILifebot",
            message: responseData[0].element.label_body
            
          },
          {
            id: messages.length + 1,
            author: "AILifebot",
            message:botMessage
          }
       ];
      }
      // else if(responseData.element.label_value=="fallback"){
      //   return [
      //     ...prevMessages,
      //     {
      //       id: messages.length + 1,
      //       author: "AILifebot",
      //       message:responseData.element.label_body
      //     }
      //   ]
      // }
      else{
        return [
          ...prevMessages,
          {
            id: messages.length + 1,
            author: "AILifebot",
            message:botMessage
          }
        ]
      }
    })
    }
    //var objDiv = document.getElementById("your_div");
    // window.setInterval(function() {
    // var objDiv = document.getElementById("your_div");
    // objDiv.scrollTop = objDiv.scrollHeight;
    // },5000)
  }, [responseData]);

  return (
    <div className="root">
      <div className="chatbot-wrapper">
        <div className="chatbot-container">
          <div className="chatbot-subtitle">
            <div className="chat-header-text">Jaquar</div>
          </div>
          <div className="chatbot-content" id="your_div">
            {messages.map((message) => {
              return (
                <div
                  key={message.id}
                  className={`message-wrapper ${
                    message.author === "User"
                      ? "message-wrapper-user"
                      : "message-wrapper-bot"
                  }`}
                >
                {/* <div className="message">{message.message}</div> */}
                  {Array.isArray(message.message)==true ?
                    <div className="message-btn">{message.message}</div>:
                    <div className="message">{message.message}</div>
                  }
                  <div ref={messagesEndRef} />
                </div>
              );
            })}
          </div>
          <div className="input-wrapper">
            <input
              placeholder="Type your message here"
              className="input"
              name="message"
              type="text"
              value={message}
              onChange={onChange}
              ref={inputRef}
              autoFocus
              onKeyUp={(e) => {
                if (e.keyCode === 13) {
                  sendMessage();
                  handleClick();
                }
              }}
              onKeyDown={(e) => {
                if (e.keyCode === 13) {
                  setactiveSuggestion();
                }
              }}
            />
            <div className="input-icon microphone-icon-container mr-3" ref={microphoneRef} onClick={handleListing}>
              <MicIcon active={isListening==true}/>
            </div>
              <div className="input-icon" onClick={()=>{sendMessage();handleClick();}}>
              <SendIcon active={message.length} />
            </div>
          </div>
          {suggestionsListComponent}
          <div style={{ color:'#000', padding:'10px',fontSize:'12px', textAlign:'center'}}>
            Powered by <span style={{fontWeight:'bold', fontSize:'12px', color:"#ea6620"}}>AILifebot</span>
            </div>
        </div>
        {/* <AudioRecognition/> */}
      </div>
    </div>
  );
};

export default React.memo(Chatbot);

